  "coverage": [
    {
      "text": "先",
      "role": "RELATION",
      "explanation": "Marks the first action in the sequence. It establishes that the following 45-degree right turn is executed first, not as a later or repeated step."
    },
    {
      "text": "右转",
      "role": "ACTION",
      "explanation": "Requests a turn skill. The direction is right/clockwise, so the compiled angle sign must be negative."
    },
    {
      "text": "45度",
      "role": "QUANTITY",
      "explanation": "Sets the first turn magnitude to exactly 45 degrees. Combined with 右转, this authorizes angle_deg -45.0."
    },
    {
      "text": "，",
      "role": "SEPARATOR",
      "explanation": "Punctuation separating the first and second clauses. It is not executable and does not alter action count or order."
    },
    {
      "text": "接着",
      "role": "RELATION",
      "explanation": "Indicates that the next instructed action follows the first action in linear order. It does not change the first action or add a separate action by itself."
    },
    {
      "text": "同一个方向",
      "role": "RELATION",
      "explanation": "Resolves the second turn's direction by reference to the first turn: the same direction as 右转, i.e. right/clockwise, so the second angle sign is also negative."
    },
    {
      "text": "再",
      "role": "RELATION",
      "explanation": "Signals an additional distinct turn action rather than replacement of the prior turn. It does not authorize compressing both turns into one action or changing the first turn."
    },
    {
      "text": "转",
      "role": "ACTION",
      "explanation": "Requests the second turn skill. Its direction comes from 同一个方向, so it is a right/clockwise turn with negative angle."
    },
    {
      "text": "30度",
      "role": "QUANTITY",
      "explanation": "Sets the second turn magnitude to exactly 30 degrees. With the referenced right/clockwise direction, this authorizes angle_deg -30.0."
    },
    {
      "text": "。",
      "role": "SEPARATOR",
      "explanation": "Terminal punctuation. It is not executable and does not alter the authorized plan."
    }
  ],
  "dimensions": {
    "action_multiplicity": {
      "status": "UNIQUE",
      "explanation": "The source requests exactly two turn actions: 先右转45度 and then 同一个方向再转30度. The adverb 再 introduces an additional distinct action, not a replacement of the first action and not a repetition count."
    },
    "action_order": {
      "status": "UNIQUE",
      "explanation": "The sequence words 先 and 接着 establish one exact linear order: first the 45-degree right turn, then the 30-degree turn in the same direction. No alternative order is permitted."
    },
    "correction_scope": {
      "status": "UNIQUE",
      "explanation": "There is no correction or edit clause in the source. No earlier action, parameter, or relation is replaced, so both requested turns are preserved."
    },
    "repetition_scope": {
      "status": "UNIQUE",
      "explanation": "No repetition count or repeated identical span is specified. 再 here means an additional distinct turn action with a different magnitude, not a repetition of the 45-degree turn and not a repeated sequence."
    },
    "reference_resolution": {
      "status": "UNIQUE",
      "explanation": "同一个方向 has exactly one source referent: the direction of the immediately preceding 右转, i.e. right/clockwise. This supplies the omitted direction argument for the second turn."
    },
    "temporal_relations": {
      "status": "UNIQUE",
      "explanation": "先 followed by 接着 and the second clause gives a single sequential relation: the first turn occurs, then the second turn occurs. No simultaneous, waiting, or completion relation is left open."
    },
    "unresolved_relations": {
      "status": "UNIQUE",
      "explanation": "The source does not explicitly leave any action, parameter, order, direction, or repetition relation unresolved. Both turns, their order, and the shared right/clockwise direction are resolved from the text."
